CREATE TABLE "_jazz_array_members_v1_6:grants_7:targets" (member BLOB NOT NULL CHECK(length(member)=16), kind INTEGER NOT NULL CHECK(kind IN(0,1)), id BLOB NOT NULL CHECK(length(id)=16), branch BLOB NOT NULL, seq INTEGER NOT NULL CHECK(seq>0), PRIMARY KEY(member,kind,id,branch,seq)) WITHOUT ROWID;
CREATE INDEX "_jazz_array_members_v1_6:grants_7:targets_row" ON "_jazz_array_members_v1_6:grants_7:targets"(kind,id,branch,seq);
CREATE TRIGGER "_jazz_array_members_v1_6:grants_7:targets_0_insert" AFTER INSERT ON "grants" BEGIN INSERT OR IGNORE INTO "_jazz_array_members_v1_6:grants_7:targets"(member,kind,id,branch,seq) SELECT unhex(replace(e.value,'-','')), 0, new.id, new._b, new._seq FROM json_each(new."targets") e WHERE e.type='text' AND length(unhex(replace(e.value,'-','')))=16; END;
CREATE TRIGGER "_jazz_array_members_v1_6:grants_7:targets_0_delete" AFTER DELETE ON "grants" BEGIN DELETE FROM "_jazz_array_members_v1_6:grants_7:targets" WHERE kind=0 AND id=old.id AND branch=old._b AND seq=old._seq; END;
